export default function ResultViewer({ data }: any) {
  if (!data) return null;

  return (
    <div className="p-4 border rounded-lg">
      <h2 className="font-bold text-lg">Results</h2>

      <p>Total: {data.num_detections}</p>

      <div className="mt-3 space-y-2">
        {data.detections.map((d: any, i: number) => (
          <div key={i} className="border p-2 rounded">
            <p><b>Class:</b> {d.class}</p>
            <p><b>Confidence:</b> {d.confidence_percent}</p>
            <p><b>BBox:</b> {d.bbox.join(", ")}</p>
          </div>
        ))}
      </div>
    </div>
  );
}