"use client";

type Props = {
  conf: number;
  setConf: (v: number) => void;
  iou: number;
  setIou: (v: number) => void;
};

export default function Controls({
  conf,
  setConf,
  iou,
  setIou,
}: Props) {
  return (
    <div className="p-4 border rounded-lg space-y-4">
      <div>
        <label>Confidence: {conf.toFixed(2)}</label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={conf}
          onChange={(e) => setConf(Number(e.target.value))}
          className="w-full"
        />
      </div>

      <div>
        <label>IOU: {iou.toFixed(2)}</label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={iou}
          onChange={(e) => setIou(Number(e.target.value))}
          className="w-full"
        />
      </div>
    </div>
  );
}